import{_ as i,a0 as r,w as p,s as h,ao as s,I as n,x as a,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux who 命令 – 顯示系統登錄者 | LCTT x X-CMD","titleTemplate":false,"description":"Linux who 命令 – 顯示系統登錄者 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux who 命令 – 顯示系統登錄者 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux who 命令 – 顯示系統登錄者 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linux who command – Displays who is on the system","title":"Linux who 命令 – 顯示系統登錄者","tag":"201401","desc":""},"relativePath":"201401/Linux who command – Displays who is on the system.md","filePath":"[post].md"}'),d={name:"201401/Linux who command – Displays who is on the system.md"};function m(w,o,u,x,c,g){const e=r("Link");return p(),h("div",null,[o[13]||(o[13]=s(`<h1 id="linux-who-命令-–-顯示系統登錄者" tabindex="-1">Linux who 命令 – 顯示系統登錄者 <a class="header-anchor" href="#linux-who-命令-–-顯示系統登錄者" aria-label="Permalink to “Linux who 命令 – 顯示系統登錄者”">​</a></h1><p>作為一名系統管理員，我們需要弄清楚在一個特定的時間點都有誰活躍在系統上。必須嚴密監視我們的服務器。但是，我們當然不可能一天24小時都盯着系統。在linux系統中，我們可以使用who命令查看登錄者信息。</p><h3 id="什麼是-who-命令" tabindex="-1">什麼是 who 命令 <a class="header-anchor" href="#什麼是-who-命令" aria-label="Permalink to “什麼是 who 命令”">​</a></h3><p><strong>who</strong>命令能夠打印 <strong>當前都有誰登錄到系統中</strong> 的相關信息 。who命令只會顯示真正登錄到系統中的用户。它不會顯示那些通過<strong>su</strong>命令切換用户的登錄者。</p><h3 id="如何使用who命令" tabindex="-1">如何使用who命令 <a class="header-anchor" href="#如何使用who命令" aria-label="Permalink to “如何使用who命令”">​</a></h3><p>在大多數linux發行版中，who命令都是默認安裝上的。想使用該命令，只需在控制台敲命令就行了。不帶選項的話，運行該命令產生默認輸出。</p><pre><code>$ who
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_default.png" alt=""></p><h4 id="如何理解輸出" tabindex="-1">如何理解輸出: <a class="header-anchor" href="#如何理解輸出" aria-label="Permalink to “如何理解輸出:”">​</a></h4><ul><li>第一列顯示用户名稱</li><li>第二列顯示用户連接方式。Tty意味着用户直接連接到電腦上，而pts意味着遠程登錄。</li><li>第三、四列分別顯示日期和時間</li><li>第五列顯示用户登錄IP地址。</li></ul><h3 id="使用帶參數的who命令" tabindex="-1">使用帶參數的who命令 <a class="header-anchor" href="#使用帶參數的who命令" aria-label="Permalink to “使用帶參數的who命令”">​</a></h3><p>Who命令有一些參數用於調整輸出。以下是常用的例子。</p><h4 id="顯示上一次重新啓動的時間和日期" tabindex="-1">顯示上一次重新啓動的時間和日期 <a class="header-anchor" href="#顯示上一次重新啓動的時間和日期" aria-label="Permalink to “顯示上一次重新啓動的時間和日期”">​</a></h4><p>使用 <strong>-b</strong> 選項</p><pre><code>$ who -b
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_b.png" alt=""></p><p>可以看到系統啓動是在2013年12月21日，下午3:52。</p><h4 id="顯示初始化進程的當前運行級別" tabindex="-1">顯示初始化進程的當前運行級別 <a class="header-anchor" href="#顯示初始化進程的當前運行級別" aria-label="Permalink to “顯示初始化進程的當前運行級別”">​</a></h4><p>使用 -r 選項，who命令會打印出初始化進程的當前運行級別</p><pre><code>$ who -r
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_r.png" alt=""></p><p>輸出顯示2013年12月21日，下午3:52系統以 級別2 開始運行。</p><h4 id="為每一列添加標題" tabindex="-1">為每一列添加標題 <a class="header-anchor" href="#為每一列添加標題" aria-label="Permalink to “為每一列添加標題”">​</a></h4><p>使用 -H 選項為每一列添加標題</p><pre><code>$ who -H
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_H.png" alt=""></p><h4 id="只打印當前運行終端的相關信息" tabindex="-1">只打印當前運行終端的相關信息 <a class="header-anchor" href="#只打印當前運行終端的相關信息" aria-label="Permalink to “只打印當前運行終端的相關信息”">​</a></h4><p>可以使用<strong>-m</strong>選項。</p><pre><code>$ who -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_m.png" alt=""></p><h4 id="對當前登錄用户數量計數" tabindex="-1">對當前登錄用户數量計數 <a class="header-anchor" href="#對當前登錄用户數量計數" aria-label="Permalink to “對當前登錄用户數量計數”">​</a></h4><p>如果系統同時有多人登錄在線，-q 選項協助你完成計數功能。</p><pre><code>$ who -q
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_q.png" alt=""></p><h4 id="附加空閒時間和pid信息" tabindex="-1">附加空閒時間和PID信息 <a class="header-anchor" href="#附加空閒時間和pid信息" aria-label="Permalink to “附加空閒時間和PID信息”">​</a></h4><p>默認情況下，who命令不會打印空閒時間和PID信息。如果打算顯示這些信息，使用-u選項。不要忘記使用 -H選項讓顯示的信息更加簡單易讀。</p><pre><code>$ who -u -H
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_u.png" alt=""></p><p><strong>空閒時間</strong> 包含了最近最後一次活動以來消逝的時間. 所以，00:13 意思是 用户leni已經13分鐘沒執行過命令了. <strong>(.)符號</strong> 是指該終端過去的一分鐘有過活動。在那期間，我們稱之為 “current” 。<strong>PID</strong> 是用户shell程序的進程ID號。</p><h4 id="顯示登錄進程" tabindex="-1">顯示登錄進程#### <a class="header-anchor" href="#顯示登錄進程" aria-label="Permalink to “顯示登錄進程####”">​</a></h4><p>使用<strong>-l</strong>選項</p><pre><code>$ who -l
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_l.png" alt=""></p><p>第一列只顯示系統登錄守護進程的名字。上面截圖中的數字 967, 971等是進程ID。</p><h4 id="顯示所有信息" tabindex="-1">顯示所有信息 <a class="header-anchor" href="#顯示所有信息" aria-label="Permalink to “顯示所有信息”">​</a></h4><p>使用<strong>-a</strong>選項會顯示所有信息。例如：</p><pre><code>$ who -a
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/who_a.png" alt=""></p><p>####總結#### 你會發現 who 命令跟 w 命令在某些方面有些相像。不要為此感到疑惑，為什麼linux要實現這些在功能上相近的命令。你可以使用你覺得最適合你的或者適用於某種場合的命令。請查閲who命令手冊瞭解更多詳細信息。</p>`,49)),n("ul",null,[n("li",null,[o[1]||(o[1]=a("See more at: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-who-command/#sthash.CU0bq3e4.dpuf"},{default:l(()=>[...o[0]||(o[0]=[a("http://linoxide.com/linux-command/linux-who-command/#sthash.CU0bq3e4.dpuf",-1)])]),_:1})])]),o[14]||(o[14]=n("hr",null,null,-1)),n("p",null,[o[3]||(o[3]=a("via: ",-1)),t(e,{href:"http://linoxide.com/linux-command/linux-who-command/"},{default:l(()=>[...o[2]||(o[2]=[a("http://linoxide.com/linux-command/linux-who-command/",-1)])]),_:1})]),n("p",null,[o[6]||(o[6]=a("譯者：",-1)),t(e,{href:"https://github.com/l3b2w1"},{default:l(()=>[...o[4]||(o[4]=[a("l3b2w1",-1)])]),_:1}),o[7]||(o[7]=a(" 校對：",-1)),t(e,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...o[5]||(o[5]=[a("Caroline",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[8]||(o[8]=[a("LCTT",-1)])]),_:1}),o[11]||(o[11]=a(" 原創翻譯，",-1)),t(e,{href:"http://linux.cn/"},{default:l(()=>[...o[9]||(o[9]=[a("Linux中國",-1)])]),_:1}),o[12]||(o[12]=a(" 榮譽推出",-1))])])}const P=i(d,[["render",m]]);export{T as __pageData,P as default};
